def main():
    group = json.loads((ROOT / 'docs/checks/skills-repair/group-b.json').read_text(encoding='utf-8-sig'))
    assert len(CASES) == 27 and set(CASES) == {x['name'] for x in group}
    prefix = '合成泛化测试，报告基准日明确为2026-11-04。全部主体和材料虚构；禁止联网、文件读写、发送、安装及实际法律操作。工具本轮不可用，不得伪装调用。只据本题材料与明确假设规则；没有规则则待核。请按已授权任务直接交付不超过500个汉字的最小可用成果。\n'
    result = [dict(id='repair-new-'+name, skill=name, kind='targeted', prompt=prefix+CASES[name][0], expected=CASES[name][1]) for name in (x['name'] for x in group)]
    path = ROOT / 'docs/checks/skills-repair/group-b-scenarios.json'
    path.write_text(json.dumps(result, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    print(f'Wrote {len(result)} distinct synthetic scenarios.')

if __name__ == '__main__':
    main()
